(()=>{
const rates={QAR:1,USD:0.274725,EUR:0.2345,GBP:0.2045,AED:1.0088,SAR:1.0302,KWD:0.0839,BHD:0.1033,OMR:0.1057,TND:0.812908,MAD:2.63508};
const symbols={QAR:'QAR',USD:'$',EUR:'€',GBP:'£',AED:'AED',SAR:'SAR',KWD:'KWD',BHD:'BHD',OMR:'OMR',TND:'TND',MAD:'MAD'};
let currency=localStorage.getItem('sultana-currency')||'QAR';if(!rates[currency])currency='QAR';
const fmt=n=>{const v=n*rates[currency];return `${symbols[currency]} ${v.toLocaleString(undefined,{minimumFractionDigits:currency==='QAR'?0:2,maximumFractionDigits:2})}`};
const priceSelectors='.price,.detail-price,#bag-total,.cart-total,.cart-subtotal,.subtotal,.total,[data-price-display],[data-money]';
const captureQar=el=>{if(el.dataset.qar)return;const m=el.textContent.match(/QAR\s*([\d,.]+)/i);if(m)el.dataset.qar=m[1].replace(/,/g,'')};
const convertText=()=>document.querySelectorAll(priceSelectors).forEach(el=>{captureQar(el);if(el.dataset.qar){const next=fmt(Number(el.dataset.qar));if(el.textContent!==next)el.textContent=next}});
const ensureOptions=()=>document.querySelectorAll('#currency-select').forEach(s=>{if(!s.querySelector('option[value="TND"]'))s.insertAdjacentHTML('beforeend','<option value="TND">🇹🇳 TND</option>');if(!s.querySelector('option[value="MAD"]'))s.insertAdjacentHTML('beforeend','<option value="MAD">🇲🇦 MAD</option>')});
const hideOldVisualMenu=()=>{document.querySelectorAll('section').forEach(sec=>{const t=(sec.textContent||'').replace(/\s+/g,' ').trim().toLowerCase();if((t.includes('explore sultana')||t.includes('discover our world'))&&t.includes('wedding')&&t.includes('hospitality'))sec.style.setProperty('display','none','important')})};
const installHeader=()=>{const h=document.querySelector('header');if(!h)return;h.dataset.luxuryHeader='1';const nav=h.querySelector('nav'),brand=h.querySelector('.brand'),actions=h.querySelector('.header-actions');if(!nav||!brand||!actions)return;
let left=h.querySelector('.luxury-header-left');if(!left){left=document.createElement('div');left.className='luxury-header-left';left.innerHTML='<span class="header-country">Qatar</span><span class="header-sep">|</span>';const cur=actions.querySelector('#currency-select'),lang=actions.querySelector('.language-switch');if(cur)left.appendChild(cur);left.insertAdjacentHTML('beforeend','<span class="header-sep">|</span>');if(lang)left.appendChild(lang);h.appendChild(left)}
nav.innerHTML='';[['Home','/'],['Perfumes','/shop/?collection=perfume#collection'],['Luxury Spray','/room-sprays/'],['Oud & Bakhoor','/oud-bakhoor/'],['B2B','/b2b/'],['Our Story','/our-story/'],['Contact','/contact/']].forEach(([label,href])=>{const a=document.createElement('a');a.href=href;a.textContent=label;nav.appendChild(a)});
let style=document.getElementById('sultana-luxury-header');if(!style){style=document.createElement('style');style.id='sultana-luxury-header';style.textContent=`.language-switch{border:0!important;outline:0!important;box-shadow:none!important;background:transparent!important;border-radius:0!important}@media(min-width:851px){header[data-luxury-header]{display:grid!important;grid-template-columns:1fr auto 1fr!important;grid-template-rows:112px 42px!important;column-gap:24px!important;row-gap:0!important;height:154px!important;min-height:154px!important;padding:0 5%!important;align-items:center!important;background:#fffdfa!important;border-bottom:1px solid #e5dccf!important}header[data-luxury-header] .luxury-header-left{grid-column:1;grid-row:1;display:flex!important;align-items:center;gap:12px;justify-self:start;font-size:12px;white-space:nowrap}header[data-luxury-header] .luxury-header-left .currency-select{width:auto!important;max-width:110px!important;padding:5px 0!important;margin:0!important;border:0!important;background:transparent!important;font-size:12px!important}header[data-luxury-header] .luxury-header-left .language-switch{padding:5px 0!important;font-size:12px!important}header[data-luxury-header]>.brand{position:static!important;grid-column:2!important;grid-row:1!important;justify-self:center!important;align-self:center!important;width:92px!important;height:104px!important;margin:0!important;transform:none!important}header[data-luxury-header]>.brand img{display:block!important;width:100%!important;height:100%!important;object-fit:contain!important}header[data-luxury-header]>.header-actions{grid-column:3!important;grid-row:1!important;justify-self:end!important;align-self:center!important;display:flex!important;align-items:center!important;gap:18px!important;margin:0!important}header[data-luxury-header]>.header-actions .currency-select,header[data-luxury-header]>.header-actions .language-switch{display:none!important}header[data-luxury-header]>nav{position:static!important;grid-column:1/-1!important;grid-row:2!important;display:flex!important;justify-content:center!important;align-items:center!important;gap:clamp(26px,3.1vw,54px)!important;width:100%!important;height:42px!important;margin:0!important;padding:0!important;font-size:11px!important;letter-spacing:.35px!important;text-transform:uppercase!important;background:transparent!important;transform:none!important}header[data-luxury-header]>nav>a{display:block!important;padding:12px 0!important;white-space:nowrap!important;color:inherit!important}header[data-luxury-header] .menu-toggle{display:none!important}}@media(max-width:850px){header[data-luxury-header] .luxury-header-left{display:none!important}}`;document.head.appendChild(style)}};
const sync=()=>{ensureOptions();document.querySelectorAll('#currency-select').forEach(s=>s.value=currency);convertText();installHeader();hideOldVisualMenu()};
document.addEventListener('change',e=>{if(e.target.id==='currency-select'){currency=e.target.value;localStorage.setItem('sultana-currency',currency);sync()}});new MutationObserver(()=>{convertText();hideOldVisualMenu()}).observe(document.body,{subtree:true,childList:true});document.addEventListener('DOMContentLoaded',sync);window.addEventListener('load',sync);window.SultanaCurrency={formatQAR:fmt,get:()=>currency,refresh:sync};
})();